<?php
require __DIR__.'/../includes/bootstrap.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}check_csrf();$u=current_user();$sid=filter_input(INPUT_POST,'submission_id',FILTER_VALIDATE_INT);$decision=(string)($_POST['decision']??'');$notes=trim((string)($_POST['review_notes']??''));if(!$sid||!in_array($decision,['approved','changes_requested','rejected'],true)||mb_strlen($notes)>5000){flash('Invalid review request.','error');header('Location: /OpenBounty/bounties/');exit;}
$s=db()->prepare('SELECT s.id,s.bounty_id,s.status,s.contributor_id,b.creator_id FROM submissions s JOIN bounties b ON b.id=s.bounty_id WHERE s.id=?');$s->execute([$sid]);$row=$s->fetch();if(!$row){http_response_code(404);exit('Submission not found.');}if((int)$row['creator_id']!==(int)$u['id']&&!in_array($u['role'],['reviewer','admin'],true)){http_response_code(403);exit('Only the bounty creator or an authorized reviewer can review this submission.');}if((int)$row['contributor_id']===(int)$u['id']){http_response_code(403);exit('You cannot review your own submission.');}if(!in_array($row['status'],['submitted','in_review','changes_requested'],true)){flash('This submission has already been finalized.','error');header('Location: '.safe_path($_POST['return']??'','/OpenBounty/bounties/view.php?id='.(int)$row['bounty_id']));exit;}
$new=$decision==='approved'?'approved':$decision;$pdo=db();$pdo->beginTransaction();try{$s=$pdo->prepare('UPDATE submissions SET status=?,reviewer_id=?,review_notes=?,reviewed_at=NOW() WHERE id=? AND status IN (\'submitted\',\'in_review\',\'changes_requested\')');$s->execute([$new,$u['id'],$notes,$sid]);if($s->rowCount()!==1)throw new RuntimeException('Submission changed while reviewing.');if($decision==='approved'){$s=$pdo->prepare("UPDATE bounties SET status='approved' WHERE id=? AND status IN ('open','in_review')");$s->execute([$row['bounty_id']]);}audit((int)$u['id'],'submission_'.$decision,'submission',$sid);$pdo->commit();flash('Review decision saved. Payment is not initiated in this batch.','success');}catch(Throwable $e){$pdo->rollBack();error_log($e->getMessage());flash('Could not save review decision. Please try again.','error');}header('Location: '.safe_path($_POST['return']??'','/OpenBounty/bounties/view.php?id='.(int)$row['bounty_id']));exit;
